package connectors

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"maps"
	"net/http"
	"regexp"
	"slices"
	"strings"
)

var temporaryResourcePattern = regexp.MustCompile(`^#?aw_[A-Za-z0-9_]{3,12}$`)

// CreatedResourceHost is trusted invocation-local state, never agent input or
// persisted configuration. Key and Run must be freshly generated by the host.
type CreatedResourceHost struct {
	Run      string
	Key      []byte
	Receipts []string
}

type createdResourceReceipt struct {
	Run, Digest, Connector, Producer, Endpoint, Resource, Scope, ScopeValue, TemporaryID, Value string
}

func (s *ConnectorSpec) validateCreatedResources() error {
	for name, op := range s.SafeOutputs {
		if created := op.Creates; created != nil {
			scope, exists := op.Inputs[created.Scope]
			temporary, declared := op.Inputs[created.TemporaryID]
			if op.Request.Method != http.MethodPost || !namePattern.MatchString(created.Resource) || !validPointer(created.Value) ||
				!exists || !scope.Required || scope.Type != "string" || op.Resources[created.Scope] == "" ||
				!declared || temporary.Type != "string" || temporary.MaxLength > 80 || temporary.Pattern != temporaryResourcePattern.String() ||
				len(created.ScopePrefix) > 16 || strings.Contains(created.ScopePrefix, "${") {
				return fmt.Errorf("safe-output %q creates requires a POST, projected value pointer, exact scoped string input, and bounded temporary-ID input", name)
			}
		}
		for input, producer := range op.CreatedResources {
			creator, exists := s.SafeOutputs[producer]
			if !exists || producer == name || creator.Creates == nil || op.Resources[input] != creator.Creates.Resource ||
				s.Endpoints[op.Request.Endpoint] != s.Endpoints[creator.Request.Endpoint] {
				return fmt.Errorf("safe-output %q createdResources must bind a constrained input to a creator on the same endpoint and resource collection", name)
			}
		}
	}
	for _, tool := range s.MCP {
		if tool.Creates != nil || len(tool.CreatedResources) > 0 {
			return errors.New("created-resource bindings are only available in safe-output operations")
		}
	}
	for _, op := range s.Context {
		if op.Creates != nil || len(op.CreatedResources) > 0 {
			return errors.New("created-resource bindings are only available in safe-output operations")
		}
	}
	return nil
}

func (p *Plan) selectedCreator(op Operation, input string) bool {
	producer, exists := op.CreatedResources[input]
	return exists && slices.Contains(p.binding.SafeOutputs, producer)
}

func (host CreatedResourceHost) validate() error {
	if len(host.Key) != 32 || host.Run == "" || len(host.Run) > 128 || len(host.Receipts) > 128 {
		return errors.New("created-resource operations require fresh trusted execution state")
	}
	size := 2
	for _, token := range host.Receipts {
		size += len(token) + 3
	}
	if size > MaxDocumentBytes {
		return errors.New("created-resource receipt state exceeds its byte bound")
	}
	return nil
}

func (host CreatedResourceHost) sign(receipt createdResourceReceipt) (string, error) {
	payload, err := json.Marshal(receipt)
	if err != nil {
		return "", err
	}
	mac := hmac.New(sha256.New, host.Key)
	if _, err := mac.Write(payload); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(payload) + "." + base64.RawURLEncoding.EncodeToString(mac.Sum(nil)), nil
}

func (p *Plan) readCreatedReceipt(host CreatedResourceHost, token string) (createdResourceReceipt, error) {
	var receipt createdResourceReceipt
	payload, signature, present := strings.Cut(token, ".")
	if !present || len(token) > 8192 {
		return receipt, errors.New("invalid created-resource receipt")
	}
	data, err := base64.RawURLEncoding.DecodeString(payload)
	if err != nil {
		return receipt, errors.New("invalid created-resource receipt")
	}
	actual, err := base64.RawURLEncoding.DecodeString(signature)
	if err != nil {
		return receipt, errors.New("invalid created-resource receipt")
	}
	mac := hmac.New(sha256.New, host.Key)
	if _, err := mac.Write(data); err != nil {
		return receipt, err
	}
	if !hmac.Equal(actual, mac.Sum(nil)) {
		return receipt, errors.New("created-resource receipt authentication failed")
	}
	if err := Decode(data, &receipt); err != nil {
		return receipt, errors.New("invalid created-resource receipt")
	}
	if receipt.Run != host.Run || receipt.Digest != p.Digest || receipt.Connector != p.spec.ID {
		return receipt, errors.New("created-resource receipt belongs to a different execution or connector plan")
	}
	creator, exists := p.spec.SafeOutputs[receipt.Producer]
	if !exists || creator.Creates == nil || !slices.Contains(p.binding.SafeOutputs, receipt.Producer) ||
		receipt.Endpoint != p.spec.Endpoints[creator.Request.Endpoint] || receipt.Resource != creator.Creates.Resource ||
		receipt.Scope != creator.Creates.Scope || !temporaryResourcePattern.MatchString(receipt.TemporaryID) {
		return receipt, errors.New("created-resource receipt does not match the approved creation scope")
	}
	_, trustedScope := creator.TrustedInputs[receipt.Scope]
	if !trustedScope && !slices.Contains(p.connection.Resources[creator.Resources[receipt.Scope]], receipt.ScopeValue) {
		return receipt, errors.New("created-resource receipt does not match the approved creation scope")
	}
	return receipt, nil
}

func (p *Plan) createdResourcePlan(host CreatedResourceHost, name string, args map[string]any) (*Plan, map[string]any, error) {
	if err := host.validate(); err != nil {
		return nil, nil, err
	}
	op := p.spec.SafeOutputs[name]
	receipts := map[string]createdResourceReceipt{}
	for _, token := range host.Receipts {
		receipt, err := p.readCreatedReceipt(host, token)
		if err != nil {
			return nil, nil, err
		}
		if _, exists := receipts[receipt.TemporaryID]; exists {
			return nil, nil, errors.New("duplicate created-resource receipt")
		}
		receipts[receipt.TemporaryID] = receipt
	}
	if op.Creates != nil {
		if temporary, ok := args[op.Creates.TemporaryID].(string); ok {
			if _, duplicate := receipts[strings.TrimPrefix(temporary, "#")]; duplicate {
				return nil, nil, errors.New("temporary created-resource reference is already bound")
			}
		}
	}
	resolved := maps.Clone(args)
	plan := *p
	plan.connection.Resources = maps.Clone(p.connection.Resources)
	for input, producer := range op.CreatedResources {
		value, ok := args[input].(string)
		if !ok || !temporaryResourcePattern.MatchString(value) {
			continue
		}
		receipt, exists := receipts[strings.TrimPrefix(value, "#")]
		if !exists || receipt.Producer != producer || receipt.Resource != op.Resources[input] ||
			receipt.Endpoint != p.spec.Endpoints[op.Request.Endpoint] {
			return nil, nil, errors.New("unknown or mismatched temporary created-resource reference")
		}
		resolved[input] = receipt.Value
		resource := op.Resources[input]
		plan.connection.Resources[resource] = append(slices.Clone(plan.connection.Resources[resource]), receipt.Value)
	}
	return &plan, resolved, nil
}

// ExecuteCreatedSafeOutput resolves only authenticated temporary references,
// then reuses normal typed validation, credential boundaries and response checks.
func (p *Plan) ExecuteCreatedSafeOutput(ctx context.Context, runtime Runtime, host CreatedResourceHost, name string, args map[string]any) (*Result, error) {
	if err := host.validate(); err != nil {
		return nil, err
	}
	trusted, inputs, err := p.createdResourcePlan(host, name, args)
	if err != nil {
		return nil, err
	}
	plan, resolved, err := trusted.resolveTrustedInputs(ctx, runtime, name, inputs)
	if err != nil {
		return nil, err
	}
	request, err := plan.PrepareSafeOutput(name, resolved)
	if err != nil {
		return nil, err
	}
	result, err := plan.ExecuteSafeOutput(ctx, runtime, *request)
	if err != nil {
		return nil, err
	}
	op := p.spec.SafeOutputs[name]
	if op.Creates == nil {
		return result, nil
	}
	temporary, supplied := args[op.Creates.TemporaryID].(string)
	if !supplied {
		return result, nil
	}
	var document any
	if err := decodeJSON(result.Data, &document); err != nil {
		return nil, errors.New("created-resource response is not valid JSON")
	}
	value, present := lookupPointer(document, op.Creates.Value)
	text, isString := value.(string)
	if !present || !isString || text == "" || len(text) > 256 {
		return nil, errors.New("created-resource response is missing its bounded resource identifier; no binding established")
	}
	for _, consumer := range p.spec.SafeOutputs {
		for input, producer := range consumer.CreatedResources {
			if producer == name {
				if err := validateArgument(consumer.Inputs[input], text); err != nil {
					return nil, errors.New("created-resource identifier violates a consumer constraint; no binding established")
				}
			}
		}
	}
	scope, ok := resolved[op.Creates.Scope].(string)
	if !ok {
		return nil, errors.New("created-resource scope is unavailable; no binding established")
	}
	if op.Creates.ScopePrefix != "" && !strings.HasPrefix(text, scope+op.Creates.ScopePrefix) {
		return nil, errors.New("created-resource identifier does not match the approved creation scope; no binding established")
	}
	result.CreatedResource, err = host.sign(createdResourceReceipt{
		Run: host.Run, Digest: p.Digest, Connector: p.spec.ID, Producer: name,
		Endpoint: p.spec.Endpoints[op.Request.Endpoint], Resource: op.Creates.Resource,
		Scope: op.Creates.Scope, ScopeValue: scope, TemporaryID: strings.TrimPrefix(temporary, "#"), Value: text,
	})
	return result, err
}

// PrepareSafeOutputIntent supports temporary references in credential-free
// staging only. Such an intent cannot be executed through ExecuteSafeOutput.
func (p *Plan) PrepareSafeOutputIntent(name string, args map[string]any) (*SafeOutputRequest, error) {
	op := p.spec.SafeOutputs[name]
	plan := *p
	plan.spec.SafeOutputs = maps.Clone(p.spec.SafeOutputs)
	op.Inputs = maps.Clone(op.Inputs)
	op.Resources = maps.Clone(op.Resources)
	plan.connection.Resources = maps.Clone(p.connection.Resources)
	resolved := maps.Clone(args)
	for input := range op.TrustedInputs {
		delete(op.Inputs, input)
		delete(op.Resources, input)
	}
	op.TrustedInputs = nil
	op.Preflight = nil
	for input := range op.CreatedResources {
		value, ok := args[input].(string)
		if !ok || !temporaryResourcePattern.MatchString(value) || !p.selectedCreator(op, input) {
			continue
		}
		field := op.Inputs[input]
		field.Pattern = temporaryResourcePattern.String()
		field.Enum = nil
		op.Inputs[input] = field
		value = strings.TrimPrefix(value, "#")
		resolved[input] = value
		resource := op.Resources[input]
		plan.connection.Resources[resource] = append(slices.Clone(plan.connection.Resources[resource]), value)
	}
	plan.spec.SafeOutputs[name] = op
	return plan.PrepareSafeOutput(name, resolved)
}
